// Copies Doodle UI e-mail templates (doodle-ui/email/*.html|txt, generated by its src/build.js) into
// src/lib/email/templates.ts as string constants (no runtime fs → works in serverless bundles),
// and the logo PNGs into public/email-assets/. Usage: node scripts/sync-email-templates.mjs [path/to/doodle-ui/email]
import fs from 'node:fs';
import path from 'node:path';
const src = process.argv[2] || '../doodle-ui/email';
const read = (f) => fs.readFileSync(path.join(src, f), 'utf8');
const out = `// GENERATED by scripts/sync-email-templates.mjs from Doodle UI email/ – do not edit by hand.
export const TEMPLATES = ${JSON.stringify({
  invitation: { html: read('invitation.html'), text: read('invitation.txt') },
  reminder: { html: read('reminder.html'), text: read('reminder.txt') },
}, null, 2)} as const;
`;
fs.mkdirSync('src/lib/email', { recursive: true });
fs.writeFileSync('src/lib/email/templates.ts', out);
fs.mkdirSync('public/email-assets', { recursive: true });
for (const f of fs.readdirSync(path.join(src, 'assets'))) if (f.endsWith('.png')) fs.copyFileSync(path.join(src, 'assets', f), path.join('public/email-assets', f));
console.log('email templates synced');
